CREATE TABLE items (id TEXT PRIMARY KEY, parent_id TEXT, name TEXT NOT NULL, kind TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, mtime INTEGER NOT NULL DEFAULT 0, etag TEXT, ctag TEXT, quickxor TEXT, mime TEXT, placement TEXT NOT NULL, thumb_key TEXT, local_handle BLOB, local_seq INTEGER NOT NULL DEFAULT 0);
CREATE INDEX items_parent ON items(parent_id);
CREATE INDEX items_handle ON items(local_handle);
CREATE TABLE staging (id TEXT PRIMARY KEY, parent_id TEXT, name TEXT NOT NULL, kind TEXT NOT NULL, size INTEGER NOT NULL DEFAULT 0, mtime INTEGER NOT NULL DEFAULT 0, etag TEXT, ctag TEXT, quickxor TEXT, mime TEXT, placement TEXT NOT NULL, thumb_key TEXT, local_handle BLOB, local_seq INTEGER NOT NULL DEFAULT 0);
CREATE INDEX staging_parent ON staging(parent_id);
CREATE INDEX staging_handle ON staging(local_handle);
CREATE TABLE staging_gone (id TEXT PRIMARY KEY);
CREATE INDEX items_seq ON items(local_seq);
CREATE INDEX items_unplaced ON items(id) WHERE local_handle IS NULL AND substr(placement, 1, 8) != 'skipped:';
CREATE INDEX items_skipped ON items(id) WHERE substr(placement, 1, 8) = 'skipped:';
CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE activity (id INTEGER PRIMARY KEY, at INTEGER NOT NULL, kind TEXT NOT NULL, path TEXT NOT NULL, detail TEXT NOT NULL);
CREATE TABLE conflicts (rescued TEXT PRIMARY KEY, at INTEGER NOT NULL, original TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'rescued');
CREATE TABLE deferred (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, gone INTEGER NOT NULL, parent_id TEXT, name TEXT, kind TEXT, size INTEGER, mtime INTEGER, etag TEXT, ctag TEXT, quickxor TEXT, mime TEXT, placement TEXT);
CREATE TABLE outbox_gone (id TEXT PRIMARY KEY, local_seq INTEGER NOT NULL);
CREATE TABLE leaving (id TEXT PRIMARY KEY, rel BLOB NOT NULL, handle BLOB);
CREATE TABLE leaving_items (id TEXT PRIMARY KEY, leaving TEXT NOT NULL);
CREATE TABLE outbox (seq INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, item_id TEXT, dev INTEGER, ino INTEGER, rel TEXT NOT NULL, base_etag TEXT, base_ctag TEXT, base_parent TEXT, base_name TEXT, target_parent TEXT, target_name TEXT, state TEXT NOT NULL, reason TEXT, attempts INTEGER NOT NULL DEFAULT 0, next_try INTEGER, snapshot_size INTEGER, snapshot_mtime INTEGER, snapshot_mtime_nsec INTEGER, moved_out TEXT, session_url TEXT, session_expires INTEGER, session_next INTEGER, handle BLOB, confirmed INTEGER NOT NULL DEFAULT 0, size INTEGER, bad_item TEXT, bad_item_ctag TEXT, bad_item_etag TEXT);
CREATE INDEX outbox_item ON outbox(item_id);
CREATE INDEX outbox_object ON outbox(dev, ino);
CREATE INDEX outbox_handle ON outbox(handle);
CREATE INDEX outbox_rel ON outbox(rel);
CREATE INDEX outbox_due ON outbox(state, next_try, seq);
CREATE INDEX outbox_target_parent ON outbox(target_parent);
CREATE INDEX outbox_kind ON outbox(kind);
CREATE INDEX outbox_frees ON outbox(seq) WHERE base_parent IS NOT NULL AND base_name IS NOT NULL AND (base_parent IS NOT target_parent OR base_name IS NOT target_name);
CREATE INDEX outbox_session ON outbox(session_url) WHERE session_url IS NOT NULL;
CREATE TABLE local_skipped (rel TEXT PRIMARY KEY, reason TEXT NOT NULL, at INTEGER NOT NULL, size INTEGER);
CREATE TABLE upload_sessions (url TEXT PRIMARY KEY, parent TEXT, name TEXT, opened INTEGER NOT NULL);
CREATE INDEX upload_sessions_parent ON upload_sessions(parent);
CREATE TABLE upload_openings (seq INTEGER PRIMARY KEY, parent TEXT NOT NULL, name TEXT NOT NULL, at INTEGER NOT NULL, last INTEGER);
CREATE INDEX upload_openings_parent ON upload_openings(parent);
CREATE TABLE upload_openings_left (parent TEXT NOT NULL, name TEXT NOT NULL, at INTEGER NOT NULL, last INTEGER NOT NULL, left_at INTEGER NOT NULL);
CREATE INDEX upload_openings_left_parent ON upload_openings_left(parent);
UPDATE sqlite_sequence SET seq = 10 WHERE name = 'outbox';
